      setChatMessages([
        {
          id: 1,
          type: "bot",
          text: `Welcome back, ${userData.name.split(" ")[0]}! 🌿 Your farm sensors are all operational. Soil moisture is at **${sensorData.soilMoisture}%**, temperature **${sensorData.temperature}°C**. How can I help you today?`,
        },
      ]);
    }
  }, [userData.name, sensorData.soilMoisture, sensorData.temperature]);

  // API log simulation
  useEffect(() => {
    const endpoints = [
      { method: "GET", path: "/api/sensors/live", status: 200 },
      { method: "POST", path: "/api/telemetry/ingest", status: 201 },
      { method: "GET", path: "/api/weather/forecast", status: 200 },
      { method: "PUT", path: "/api/pump/state", status: 200 },
      { method: "GET", path: "/api/market/prices", status: 200 },
      { method: "GET", path: "/api/alerts/pending", status: 200 },
    ];
    let index = 0;
    const interval = setInterval(() => {
      const endpoint = endpoints[index % endpoints.length];
      const log = {
        id: Date.now(),
        timestamp: new Date().toISOString(),
        method: endpoint.method,
        path: endpoint.path,
        status: endpoint.status,
      };
      setApiLogs((prev) => {
        const updated = [...prev, log];
        return updated.slice(-12);
      });
      index++;
    }, 3500);
    return () => clearInterval(interval);
  }, []);

  // Auto-scroll API log
  useEffect(() => {
    if (logContainerRef.current) {
      logContainerRef.current.scrollTop = logContainerRef.current.scrollHeight;
    }
  }, [apiLogs]);

  // Check scheduled timers
  useEffect(() => {
    const checkTimers = () => {
      const now = new Date();
      const currentTime = `${String(now.getHours()).padStart(2, "0")}:${String(now.getMinutes()).padStart(2, "0")}`;
      const currentDay = now.getDay();

      Object.entries(scheduledTimers).forEach(([pumpId, timers]) => {
        timers.forEach((timer) => {
          if (timer.days.includes(currentDay) && timer.startTime === currentTime && !pumps[pumpId].on) {
            togglePump(pumpId);
            toast.success(`${pumpId === "pump1" ? "Pump 1" : "Pump 2"} started by scheduled timer!`);
          }
        });
      });
    };

    const interval = setInterval(checkTimers, 60000);
    return () => clearInterval(interval);
  }, [scheduledTimers, pumps]);

  const togglePump = (pumpId) => {
    setPumps((prev) => ({
      ...prev,
      [pumpId]: {
        ...prev[pumpId],
        on: !prev[pumpId].on,
        runtime: prev[pumpId].on ? prev[pumpId].runtime : 0,
      },
    }));
    toast.success(`${pumpId === "pump1" ? "Pump 1" : "Pump 2"} turned ${pumps[pumpId].on ? "OFF" : "ON"}`);
  };

  const handleLogout = () => {
    localStorage.removeItem("cropconnect-user");
    toast.success("Logged out successfully");
    navigate("/login");
  };

  const handleSendMessage = () => {
    if (!chatInput.trim()) return;

    const userMessage = { id: Date.now(), type: "user", text: chatInput };
    setChatMessages((prev) => [...prev, userMessage]);
    setChatInput("");
    setShowSuggestions(false);
    setIsTyping(true);

    setTimeout(() => {
      const input = chatInput.toLowerCase();
      let responseKey = "default";

      for (const [key] of Object.entries(aiResponses)) {
        if (key !== "default" && input.includes(key)) {
          responseKey = key;
          break;
        }
      }

      let responseText = aiResponses[responseKey];
      if (responseKey === "default") {
        responseText = responseText
          .replace("{moisture}", sensorData.soilMoisture)
          .replace("{temp}", sensorData.temperature)
          .replace("{hum}", sensorData.humidity);
      }

      responseText = responseText.replace(/\*\*(.*?)\*\*/g, "<strong>$1</strong>");

      setChatMessages((prev) => [
        ...prev,
        { id: Date.now() + 1, type: "bot", text: responseText },
      ]);
      setIsTyping(false);
    }, 1000 + Math.random() * 800);
  };

  const handleSuggestionClick = (suggestion) => {
    setChatInput(suggestion);
    handleSendMessage();
